insert into trust_us_territories (slug, label, prompt, description, tags, sort_order) values
  ('tense', 'I want to feel tense', 'Something tense where the pressure never lets up', 'Pressure-driven films built around suspense, pursuit or tightening stakes.', array['tense', 'suspense', 'pressure', 'chase', 'claustrophobic', 'edge of seat']::text[], 1),
  ('scared', 'I want to be scared', 'Something genuinely scary and unsettling', 'Horror chosen for atmosphere, dread and the feeling that something is wrong.', array['horror', 'scary', 'creepy', 'dread', 'disturbing', 'supernatural']::text[], 2),
  ('mystery', 'I want a mystery', 'Give me a mystery I can get lost in', 'Films driven by unanswered questions, investigation, hidden motives or uncertain truth.', array['mystery', 'detective', 'investigation', 'secrets', 'puzzle', 'noir']::text[], 3),
  ('mind-bending', 'I want something mind-bending', 'Something that will mess with my head', 'Reality slips, identity blurs and the film keeps asking you to reconsider what you saw.', array['mind bending', 'surreal', 'reality', 'memory', 'identity', 'strange']::text[], 4),
  ('big-adventure', 'I want big adventure', 'A big adventure I can disappear into', 'Large-scale journeys, quests, chases and worlds that reward surrendering to the ride.', array['adventure', 'epic', 'journey', 'quest', 'action', 'escape']::text[], 5),
  ('science-fiction-wonder', 'I want science-fiction wonder', 'Science fiction that makes me feel awe', 'Speculative films built around wonder, discovery, future worlds and big human questions.', array['science fiction', 'space', 'future', 'technology', 'aliens', 'awe']::text[], 6),
  ('romance-without-clich-s', 'I want romance without clichés', 'Romantic, but complicated and not cheesy', 'Love stories with friction, restraint, ambiguity and people who feel real.', array['romance', 'longing', 'chemistry', 'complicated love', 'intimate', 'desire']::text[], 7),
  ('heartbreak', 'I want heartbreak', 'I want something that will destroy me', 'Films that land emotionally through grief, loss, regret, sacrifice or quiet devastation.', array['sad', 'cry', 'grief', 'loss', 'devastating', 'emotional']::text[], 8),
  ('warm', 'I want something warm', 'Something comforting that leaves me hopeful', 'Gentle, generous films that restore faith in people without becoming saccharine.', array['warm', 'comforting', 'hopeful', 'kind', 'gentle', 'wholesome']::text[], 9),
  ('to-laugh', 'I want to laugh', 'I just want something properly funny', 'Comedies that still work as films, from verbal wit to visual chaos.', array['funny', 'comedy', 'witty', 'silly', 'playful', 'feel good']::text[], 10),
  ('dark-comedy', 'I want dark comedy', 'Something funny, but a little wrong', 'Films that find humour inside power, violence, failure, social discomfort or moral rot.', array['dark comedy', 'satire', 'cynical', 'awkward', 'absurd', 'uncomfortable']::text[], 11),
  ('coming-of-age', 'I want coming-of-age', 'Something about growing up and figuring it out', 'Young people forming identities, leaving home, finding freedom or seeing adulthood clearly.', array['coming of age', 'youth', 'adolescence', 'school', 'first love', 'growing up']::text[], 12),
  ('family-drama', 'I want family drama', 'A family story with real emotional weight', 'Families under pressure, where love, history and resentment live in the same room.', array['family', 'parents', 'siblings', 'marriage', 'home', 'generational']::text[], 13),
  ('friendship-and-connection', 'I want friendship and connection', 'Something about friendship or finding your people', 'Films about the people who make isolation bearable, whether briefly or for life.', array['friendship', 'connection', 'chosen family', 'companionship', 'loneliness', 'community']::text[], 14),
  ('crime-and-moral-compromise', 'I want crime and moral compromise', 'A smart crime film with morally grey people', 'Crime stories where professionalism, loyalty, greed and conscience keep colliding.', array['crime', 'gangster', 'heist', 'cops', 'noir', 'moral grey']::text[], 15),
  ('ambition-and-obsession', 'I want ambition and obsession', 'Something about obsession, talent or ambition', 'People who want something badly enough to sacrifice work, love, identity or sanity.', array['ambition', 'obsession', 'perfection', 'fame', 'career', 'greatness']::text[], 16),
  ('power-and-politics', 'I want power and politics', 'Something sharp about power, politics or corruption', 'Films about institutions, ideology, propaganda, resistance and who gets to control the story.', array['politics', 'power', 'corruption', 'protest', 'systems', 'justice']::text[], 17),
  ('war-and-survival', 'I want war and survival', 'A war film that feels human, not heroic', 'War seen through survival, moral compromise, resistance and ordinary human consequence.', array['war', 'survival', 'resistance', 'conflict', 'historical', 'occupation']::text[], 18),
  ('music-and-performance', 'I want music and performance', 'Something about music, artists or performing', 'Films where performance is work, identity, escape, obsession or pure joy.', array['music', 'band', 'performance', 'artist', 'concert', 'dance']::text[], 19),
  ('beautiful-and-strange', 'I want something beautiful and strange', 'Something visually beautiful and a bit strange', 'Films where image, rhythm and atmosphere matter as much as conventional plot.', array['beautiful', 'dreamlike', 'poetic', 'visual', 'slow', 'strange']::text[], 20)
